using StardewModdingAPI;\nusing System.Collections.Generic;\nusing System.Linq;\n\nnamespace EnhancedSchoolsMod\n{\n    public class SchoolManager\n    {\n        private readonly ModConfig Config;\n        private readonly IMonitor Monitor;\n        private readonly Dictionary<string, SchoolData> Schools;\n\n        public SchoolManager(ModConfig config, IMonitor monitor)\n        {\n            Config = config;\n            Monitor = monitor;\n            Schools = InitializeSchools();\n        }\n\n        private Dictionary<string, SchoolData> InitializeSchools()\n        {\n            var schools = new Dictionary<string, SchoolData>\n            {\n                { \"PublicSchool\", new SchoolData(\"PublicSchool\", \"Public School\", \"Free local education\", 0) { AcademicsBonus = 1.0f, SocialBonus = 0.8f } },\n                { \"BoardingSchool\", new SchoolData(\"BoardingSchool\", \"Boarding School\", \"Residential school\", 5000) { AcademicsBonus = 1.5f, SocialBonus = 1.2f, IsResidential = true } },\n                { \"ArtsAcademy\", new SchoolData(\"ArtsAcademy\", \"Arts Academy\", \"Creativity focused\", 2500) { CreativityBonus = 2.0f, AcademicsBonus = 0.8f } },\n                { \"SportsAcademy\", new SchoolData(\"SportsAcademy\", \"Sports Academy\", \"Athletics focused\", 2500) { AthleticsBonus = 2.0f, SocialBonus = 1.5f } },\n                { \"MagicalAcademy\", new SchoolData(\"MagicalAcademy\", \"Magical Academy\", \"Magic focused\", 10000) { AcademicsBonus = 2.0f } }\n            };\n            Monitor.Log($\"Initialized {schools.Count} school types.\", LogLevel.Info);\n            return schools;\n        }\n\n        public SchoolData? GetSchool(string schoolId) { Schools.TryGetValue(schoolId, out var school); return school; }\n        public IEnumerable<SchoolData> GetAllSchools() => Schools.Values;\n        public bool IsSchoolDay(int dayOfWeek) => Config.SchoolOperatingDays.Contains(dayOfWeek);\n        public int GetSchoolCost(string schoolId) => Config.SchoolCosts.TryGetValue(schoolId, out var cost) ? cost : 0;\n        public bool IsResidential(string schoolId) => GetSchool(schoolId)?.IsResidential ?? false;\n        public int GetTermLengthDays() => Config.TermLengthDays;\n        public int GetBoardingSchoolReturnDay() => Config.BoardingSchoolReturnDay;\n    }\n}